def test_escape_single_quote():
    assert escape("it's") == "it&#x27;s"
    assert render("{{ x }}", {"x": "<a title='t'>"}) == "&lt;a title=&#x27;t&#x27;&gt;"

def test_query_keeps_blank_values():
    req = Request("GET", "/search?q=&page=1")
    assert req.query == {"q": "", "page": "1"}

def test_handler_exception_becomes_500(app, call):
    @app.route("/boom")
    def boom(request):
        raise RuntimeError("kaboom")

    resp = call("GET", "/boom")
    assert resp.status == 500
    assert resp.body == "Internal Server Error"
